    with open(path, "w", encoding="utf-8") as f:
        f.write(s2)


def expect_once(s, needle, path):
    n = s.count(needle)
    if n != 1:
        sys.exit(f"FATAL: {path}: expected exactly 1 occurrence, found {n}: {needle[:60]!r}")


for crate in CRATES:
    ld = f"{crate}/user.ld"
    def ld_fix(s, path=ld):
        expect_once(s, PHDRS_OLD, path)
        expect_once(s, RODATA_OLD, path)
        return s.replace(PHDRS_OLD, PHDRS_NEW).replace(RODATA_OLD, RODATA_NEW)
    edit(ld, ld_fix)

    with open(f"{crate}/build.rs", "w", encoding="utf-8") as f:
        f.write(BUILD_RS)

    mainrs = f"{crate}/src/main.rs"
    def main_fix(s, path=mainrs):
        expect_once(s, CFG_OLD, path)
        expect_once(s, ATTR_ANCHOR, path)
        s = s.replace(CFG_OLD, CFG_NEW)
        s = s.replace("bare-metal target", "minixrs target")
        return s.replace(ATTR_ANCHOR, ATTR_ANCHOR + BRAND)
    edit(mainrs, main_fix)

    toml = f"{crate}/Cargo.toml"
    def toml_fix(s, path=toml):
        if "[lints]" in s or "minixrs-abi-note" in s:
            sys.exit(f"FATAL: {path}: already edited?")
        if not s.endswith("\n"):
            s += "\n"
        return s + CARGO_APPEND
    edit(toml, toml_fix)

