233	/// Pack server ELFs into the minix.rs boot-image (MXBI) archive:
234	///
235	/// ```text
236	///   16-byte header: magic "MXBI" (LE u32), version, entry_count, total_size
237	///   entry_count × 32-byte records: { proc_nr:i32, offset:u32, len:u32, name:[u8;20] }
238	///   then the ELF payloads back-to-back, each at its recorded offset
239	/// ```
240	///
241	/// All multi-byte fields are little-endian (build host and aarch64 target are
242	/// both LE); `boot_image::BootImage` parses this with matching `from_le_bytes`.
243	fn pack_mxbi(modules: &[(i32, String, Vec<u8>)]) -> Vec<u8> {
244	    const MAGIC: u32 = 0x4942_584D; // "MXBI" as little-endian bytes M,X,B,I
245	    const VERSION: u32 = 1;
246	    const HDR_LEN: usize = 16;
247	    const REC_LEN: usize = 32;
248	    const NAME_LEN: usize = 20;
249	
250	    let n = modules.len();
251	    let payload_start = HDR_LEN + n * REC_LEN;
252	
253	    // Build the record table, assigning each payload an offset past the table.
254	    let mut offset = payload_start;
255	    let mut records = Vec::with_capacity(n * REC_LEN);
256	    for (proc_nr, name, bytes) in modules {
257	        let name_bytes = name.as_bytes();
258	        assert!(
259	            name_bytes.len() < NAME_LEN,
260	            "server name {name:?} too long for MXBI {NAME_LEN}-byte name field"
261	        );
262	        records.extend_from_slice(&proc_nr.to_le_bytes());
263	        records.extend_from_slice(&(offset as u32).to_le_bytes());
264	        records.extend_from_slice(&(bytes.len() as u32).to_le_bytes());
265	        let mut name_field = [0u8; NAME_LEN];
266	        name_field[..name_bytes.len()].copy_from_slice(name_bytes);
267	        records.extend_from_slice(&name_field);
268	        offset += bytes.len();
269	    }
270	    let total_size = offset;
271	
272	    let mut archive = Vec::with_capacity(total_size);
273	    archive.extend_from_slice(&MAGIC.to_le_bytes());
274	    archive.extend_from_slice(&VERSION.to_le_bytes());
275	    archive.extend_from_slice(&(n as u32).to_le_bytes());
276	    archive.extend_from_slice(&(total_size as u32).to_le_bytes());
277	    archive.extend_from_slice(&records);
278	    for (_, _, bytes) in modules {
279	        archive.extend_from_slice(bytes);
280	    }
281	    assert_eq!(archive.len(), total_size, "MXBI archive size mismatch");
282	    archive
283	}
